// fallback score: higher -> keep-serving; lower -> candidate for fallback
func scoreFallback(tenantToks int, recentOkRatio float64, tailLat float64) float64 {
    // delta-weighted score emphasizes sudden drops in OK ratio and tail latency spikes
    return float64(tenantToks)*0.4 + recentOkRatio*40 - tailLat*1.5
}
